Шаблон может иметь <strong>несколько</strong> параметров типа, а также <strong>нетиповые</strong> параметры:<br><pre><code>template &lt;typename K, typename V&gt;
class Pair {
    K key;
    V value;
public:
    Pair(K k, V v) : key(k), value(v) {}
    K getKey() const { return key; }
    V getValue() const { return value; }
};

Pair&lt;std::string, int&gt; p("age", 20);</code></pre>
